\title{Excluded Minors for $\mathbb{Z}/p$-Gainable Biased Graphs:\\
A Self-Contained Treatment of the Parallel-Class Obstruction}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
A \emph{biased graph} is a graph equipped with a distinguished family of \emph{balanced} cycles. A \emph{$\Zp$-gain labelling} assigns to each edge a value in the cyclic group $\Zp$ so that a cycle is balanced exactly when the signed sum of its edge labels vanishes; a biased graph is \emph{$\Zp$-gainable} when such a labelling exists. We develop a minimalist, vertex-free model of biased graphs that records only oriented cycles and their balance, and we work with the \emph{labelled minor} (weak-map) relation under which gain labellings pull back. We establish three structural facts: (i) the gain of a cycle is preserved under pull-back along a labelled-minor embedding (the \emph{pull-back identity}); (ii) $\Zp$-gainability is closed under labelled minors; (iii) the contrabalanced bundle $(p+1)K_2$ fails to be $\Zp$-gainable, by a pigeonhole argument. Combining these yields a universal necessary condition: no $\Zp$-gainable biased graph contains a $(p+1)K_2$ minor. For \emph{parallel-class} biased graphs we obtain a complete excluded-minor characterisation: such a graph is $\Zp$-gainable iff it contains no $(p+1)K_2$ minor, with both directions bridged by the number of balanced parallel classes. We situate this inside the conjectured full characterisation, whose three excluded minors are $(p+1)K_2$, the balanced triangle $\pm K_3$, and the unbalanced four-cycle $-K_4$.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
Many networks carry \emph{gains}: numerical quantities attached to oriented edges that accumulate, with sign, as one traverses a closed walk. Electrical potential differences, currency conversion factors, gauge-theoretic holonomies, and the $\pm$ signs of social balance theory are all instances. A recurring structural question is \emph{realisability}: given only a prescription of which cycles ``should'' close up (balanced) and which ``should not'' (unbalanced), does there exist an assignment of gains reproducing exactly that prescription?

When the gains take values in $\Zp$ for a prime $p$, realisability is a \emph{minor-closed} property. The guiding conjecture states: for every odd prime $p$, the class of biased graphs admitting a $\Zp$-gain labelling is minor-closed, and its only excluded minors are the contrabalanced parallel bundle $(p+1)K_2$, the balanced triangle $\pm K_3$, and the unbalanced four-cycle $-K_4$. This paper proves, completely and self-containedly, the part admitting an elementary, vertex-free combinatorial proof: the obstruction $(p+1)K_2$ and the complete characterisation for the parallel-class (digon) family.

\subsection{Contributions}
\begin{enumerate}[label=(\arabic*)]
\item A minimalist, vertex-free formalisation of biased graphs (Section~\ref{sec:defs}).
\item The pull-back identity (Theorem~\ref{thm:pullback}).
\item Minor-closedness of $\Zp$-gainability (Theorem~\ref{thm:minorclosed}; Lemma~B).
\item The pigeonhole obstruction (Theorem~\ref{thm:lemmaA}; Lemma~A).
\item A universal necessary condition (Theorem~\ref{thm:necessity}).
\item A complete excluded-minor characterisation for parallel classes (Theorem~\ref{thm:main}; Lemma~C + Theorem).
\end{enumerate}

\section{Definitions and the model}
\label{sec:defs}

\subsection{Oriented walks and the vertex-free model}
Let $E$ be a type of \emph{edges}. An \emph{oriented walk} is a finite list
\[ c = [(e_1,b_1),\ldots,(e_k,b_k)], \qquad e_i \in E,\ b_i \in \{\text{true},\text{false}\}, \]
where $b_i$ records the direction of traversal of $e_i$ (true = forward, false = backward).

\begin{definition}[Biased graph]
A \emph{biased graph} on edge type $E$ is a pair of predicates on oriented walks,
$G = (G.\isCycle,\ G.\balanced)$, where $G.\isCycle(c)$ asserts that $c$ is a cycle and $G.\balanced(c)$ asserts that $c$ is balanced.
\end{definition}

This abstraction discards the vertex set, retaining exactly the data the gain condition constrains.

\subsection{Gains and the signed sum}
Fix a prime $p$ and write $\Zp$ for the cyclic group of order $p$, the \emph{gain group}. A \emph{$\Zp$-gain labelling} is a function $g : E \to \Zp$.

\begin{definition}[Signed sum]
The \emph{signed sum} (gain) of an oriented walk $c$ under $g$ is
\[ \signedSum(g,c) = \sum_{(e,b)\in c} \big[\, b \,?\, g(e) : -g(e)\,\big] \in \Zp, \]
i.e.\ each forward edge contributes $+g(e)$ and each backward edge contributes $-g(e)$.
\end{definition}

\begin{definition}[Realisation; gainability]
A labelling $g$ \emph{realises} $G$ if for every cycle $c$,
$G.\balanced(c) \iff \signedSum(g,c) = 0$. $G$ is \emph{$\Zp$-gainable} when some labelling realises it:
\[ \Gainable_p(G) :\iff \exists\, g:E\to\Zp,\ \forall c,\ G.\isCycle(c) \Rightarrow \big(G.\balanced(c) \iff \signedSum(g,c)=0\big). \]
\end{definition}

\subsection{The labelled-minor relation}
\begin{definition}[Walk transport]
Given $\varphi : E \to F$ and a switch $\sigma : E \to \mathrm{Bool}$, define
$\mapCycle(\varphi,\sigma)(c) = [(\varphi(e),\ \sigma(e)\oplus b) : (e,b)\in c]$,
where $\oplus$ is Boolean XOR: $e$ keeps its orientation when $\sigma(e)=\text{false}$ and reverses it when $\sigma(e)=\text{true}$.
\end{definition}

\begin{definition}[Labelled minor / weak map]
$H$ on $E$ is a \emph{(labelled) minor} of $G$ on $F$, written $H \preceq G$, if there exist an injection $\varphi : E \to F$ and a switch $\sigma : E \to \mathrm{Bool}$ such that
\begin{enumerate}[label=(\roman*)]
\item $\varphi$ is injective;
\item for every $c$, $H.\isCycle(c) \Rightarrow G.\isCycle(\mapCycle(\varphi,\sigma)(c))$;
\item for every cycle $c$ of $H$, $H.\balanced(c) \iff G.\balanced(\mapCycle(\varphi,\sigma)(c))$.
\end{enumerate}
\end{definition}

\begin{definition}[Pull-back labelling]
Given $\varphi,\sigma$ and $g:F\to\Zp$, the \emph{pull-back} on $E$ is
\[ \pullGain(\varphi,\sigma,g)(e) = \begin{cases} -g(\varphi(e)) & \sigma(e)=\text{true},\\ \ \ g(\varphi(e)) & \sigma(e)=\text{false}. \end{cases} \]
\end{definition}

\subsection{The principal examples}
\begin{definition}[Contrabalanced parallel bundle $nK_2$]
For $n\in\mathbb{N}$, define $\mathrm{parallelEdges}(n)$ on $\Fin\,n$ by
$\isCycle(c) :\iff \exists\, i\neq j,\ c=[(i,\text{true}),(j,\text{false})]$ and $\balanced(c):\iff\text{False}$. Its cycles are the digons, none balanced. The case $n=p+1$ is the obstruction of interest.
\end{definition}

\begin{definition}[Parallel-class biased graph]
A \emph{parallel-class} biased graph has all edges joining the same two vertices, so its cycles are exactly the digons. A digon $[(i,\text{true}),(j,\text{false})]$ is balanced precisely when $i,j$ lie in a common balanced class (a fixed equivalence relation on edges). The bias is encoded by the number of balanced classes, the \emph{parallel-class count} $\kappa(G)$.
\end{definition}

\section{The pull-back machinery}

\begin{theorem}[Pull-back identity; \texttt{signedSum\_mapCycle}]
\label{thm:pullback}
For all $\varphi:E\to F$, $\sigma:E\to\mathrm{Bool}$, $g:F\to\Zp$, and every walk $c$,
\[ \signedSum\big(\pullGain(\varphi,\sigma,g),\ c\big) = \signedSum\big(g,\ \mapCycle(\varphi,\sigma)(c)\big). \]
\end{theorem}

\begin{proof}[Proof sketch]
Both sides are sums of per-entry contributions; it suffices to match contributions entrywise. Fix $(e,b)$. A four-way case split on $\sigma(e)$ and $b$ verifies equality, since reversing an edge and negating its label have the same effect on a signed sum. For instance, $\sigma(e)=\text{true},b=\text{true}$ gives $\pullGain(e)=-g(\varphi(e))$ on the left and $(\text{false})?\cdots = -g(\varphi(e))$ on the right; the other three cases are identical in spirit.
\end{proof}

\begin{theorem}[Minor-closedness; Lemma B; \texttt{gainable\_of\_isMinor}]
\label{thm:minorclosed}
If $\Gainable_p(G)$ and $H\preceq G$, then $\Gainable_p(H)$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $g$ realise $G$ and $(\varphi,\sigma)$ witness $H\preceq G$; take $g'=\pullGain(\varphi,\sigma,g)$. For any cycle $c$ of $H$,
\[ H.\balanced(c) \iff G.\balanced(\mapCycle\,c) \iff \signedSum(g,\mapCycle\,c)=0 \iff \signedSum(g',c)=0, \]
using Definition of $\preceq$, that $g$ realises $G$, and Theorem~\ref{thm:pullback}. Hence $g'$ realises $H$.
\end{proof}

\section{The obstruction $(p+1)K_2$}

\begin{theorem}[Lemma A; \texttt{parallelEdges\_not\_gainable}]
\label{thm:lemmaA}
For every prime $p$, the bundle $(p+1)K_2=\mathrm{parallelEdges}(p+1)$ is not $\Zp$-gainable.
\end{theorem}

\begin{proof}[Proof sketch]
Suppose $g:\Fin(p+1)\to\Zp$ realises it. For $i\neq j$, the digon $[(i,\text{true}),(j,\text{false})]$ is unbalanced, so $\signedSum(g)=g(i)-g(j)\neq 0$, i.e.\ $g(i)\neq g(j)$. Thus $g$ is injective on a set of size $p+1$, forcing $p+1\le|\Zp|=p$, a contradiction.
\end{proof}

\begin{theorem}[Universal necessity; \texttt{not\_isMinor\_parallelEdges\_of\_gainable}]
\label{thm:necessity}
Every $\Zp$-gainable biased graph $G$ contains no $(p+1)K_2$ minor:
$\Gainable_p(G) \Rightarrow \neg\big((p+1)K_2\preceq G\big)$.
\end{theorem}

\begin{proof}[Proof sketch]
If $(p+1)K_2\preceq G$ and $G$ were gainable, then by Theorem~\ref{thm:minorclosed} the bundle would be gainable, contradicting Theorem~\ref{thm:lemmaA}.
\end{proof}

\section{The complete characterisation for parallel classes}

Restrict to parallel-class biased graphs, with bias encoded by $\kappa(G)$.

\begin{lemma}[Gainability by counting; \texttt{digon\_gainable\_iff\_card}]
\label{lem:gain}
A parallel-class biased graph $G$ is $\Zp$-gainable iff $\kappa(G)\le p$.
\end{lemma}

\begin{proof}[Proof sketch]
($\Leftarrow$) With $k\le p$ classes, choose distinct $v_1,\ldots,v_k\in\Zp$ and set $g(e)=v_{[e]}$. Then $g(i)-g(j)=0 \iff [i]=[j] \iff$ digon balanced. ($\Rightarrow$) If $\kappa\ge p+1$, representatives of $p+1$ classes have pairwise-unbalanced digons, forcing $p+1$ distinct values in $\Zp$, impossible.
\end{proof}

\begin{lemma}[Minor by counting; \texttt{digon\_isMinor\_iff\_card}]
\label{lem:minor}
$G$ contains a $(p+1)K_2$ minor iff $\kappa(G)\ge p+1$.
\end{lemma}

\begin{proof}[Proof sketch]
($\Leftarrow$) Choose one edge from each of $p+1$ distinct classes; $\varphi$ onto these with $\sigma\equiv\text{false}$ maps each digon to an unbalanced digon, matching the all-unbalanced bias of $(p+1)K_2$. ($\Rightarrow$) An embedding injects $p+1$ edges with pairwise-unbalanced (hence inequivalent) digons, so $\kappa\ge p+1$.
\end{proof}

\begin{theorem}[Excluded-minor theorem; Lemma C + Theorem; \texttt{digon\_excluded\_minor}]
\label{thm:main}
A parallel-class biased graph $G$ is $\Zp$-gainable iff it contains no $(p+1)K_2$ minor.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:gain}, $\Gainable_p(G)\iff\kappa(G)\le p$. By Lemma~\ref{lem:minor}, $(p+1)K_2\preceq G\iff\kappa(G)\ge p+1$, whose negation is $\kappa(G)\le p$. Chaining gives the result.
\end{proof}

\section{Algorithms}

\paragraph{Gainability test.} Compute balanced classes by union--find ($O(m\,\alpha(m))$); if $\kappa>p$ return \emph{not gainable} with a $(p+1)K_2$ certificate, else label $g(e)=(\text{class index})\bmod p$.

\paragraph{Certificate extraction.} From $\kappa>p$, pick $p+1$ class representatives $e_0,\ldots,e_p$; return $\varphi(i)=e_i$, $\sigma\equiv\text{false}$ ($O(m)$).

\paragraph{Pull-back.} For each edge $e$ of $H$, set $g'(e)=-g(\varphi(e))$ if $\sigma(e)$ else $g(\varphi(e))$ ($O(|E(H)|)$).

\section{Applications}
\begin{itemize}
\item \textbf{Social balance ($p=2$).} $\Zp$ gains recover the Cartwright--Harary two-camp theorem; $3K_2$ flags an unbalanceable parallel class.
\item \textbf{Electrical / flow networks.} Gains are potential shifts; the test certifies inconsistency in near-linear time.
\item \textbf{Discrete gauge theory.} $\Zp$ gains are flat connections; balance is trivial holonomy.
\item \textbf{Constraint satisfaction.} A $(p+1)K_2$ minor is a human-readable infeasibility certificate.
\end{itemize}

\section{Discussion}
The parallel-class theorem is one panel of the conjectured three-obstruction result: $(p+1)K_2$ (proved here), the balanced triangle $\pm K_3$, and the unbalanced four-cycle $-K_4$. The latter two are vertex-dependent and connect to signed-graph theory and Dowling geometries, where the frame matroid of a $\Zp$-gain graph is $GF(p)$-representable. A telling signature is the threshold gap: gain realisability of $kK_2$ over $\Zp$ has threshold $k\le p$ (affine line $\mathbb{A}^1(\Zp)$), while $GF(p)$-representability of $U_{2,k}$ has threshold $k\le p+1$ (projective line $\mathbb{P}^1(GF(p))$); the gap of one is the point at infinity.

\section{Future work}
\begin{itemize}
\item \textbf{C1 (Theta excluded minor).} A theta graph with exactly two balanced cycles is $A$-gainable for no nontrivial group $A$, by transitivity of balance.
\item \textbf{C2 (Falling factorial count).} $|\{g:\Fin\,k\to\Zp \mid g\text{ injective}\}| = \descFactorial(p,k) = p!/(p-k)!$ for $k\le p$, else $0$ (OEIS A008279).
\item \textbf{C3 (Switching = cohomology).} Gains modulo switching biject with $(\Zp)^{m-n+1}$ for a connected graph with $n$ vertices, $m$ edges.
\item \textbf{C4 (Affine vs.\ frame threshold).} Adjoining one balanced edge to $CB(k)$ raises the threshold from $k\le p$ to $k\le p+1$.
\item \textbf{C5 (Prime vs.\ composite).} For composite $n$, partial-bias realisability of $CB(k)$ holds iff $t\le n$ (with $t$ balanced classes), enumeration governed by the subgroup lattice of $\Zp[n]$.
\end{itemize}

\section{Conclusion}
In a spare, vertex-free model we proved that $\Zp$-gainability is preserved by pulling gains back along labelled minors, hence minor-closed; that $(p+1)K_2$ is not $\Zp$-gainable by pigeonhole; and consequently that no gainable biased graph contains a $(p+1)K_2$ minor. For parallel-class biased graphs we obtained the complete excluded-minor characterisation, both directions controlled by the parallel-class count. This is the elementary core of the conjectured three-obstruction theorem.

